import{TrailWorld}from'./trail-world.js';import{TrailNavigator}from'./trail-nav.js';import{mechanismMarkup}from'./world-mechanisms.js';import{freshJourney,freshExpedition,orderFor,TASK_TYPES,activity}from'./expedition.js';import{activeNode,approachPoint}from'./trail-layout.js';import{makeTask,actTask,taskHint}from'./trail-tasks.js';import{applyGraphics,graphicsSettings}from'./render-quality.js';import{icon}from'./ui-icons.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let units=[],world,nav,e,task,busy=false,feedback='Tap the pieces on the mechanism.';
function route(){const j=freshJourney();j.level=Number($('#form').value);const state=freshExpedition(j,$('#unit').value,Number($('#area').value));state.choices.fill($('#side').value);state.index=Number($('#position').value);state.completed=Array.from({length:state.index},(_,index)=>({index,id:state.id+':'+index,type:orderFor(state,Math.floor(index/4))[index%4]}));return state;}
function render(){const plan=world.showMechanism(task),a=activity(task.type);$('#task-layer').innerHTML=`<div class="mechanism-hud"><div><span>Gate review · ${task.complete?'restored':task.kind==='pairs'?task.matched.length+' / 3':task.round+1+' / 3'}</span><strong>${esc(a.label)}</strong></div><button data-do="review" aria-label="Gate review options">${icon('more')}</button></div>${mechanismMarkup(plan)}<div class="mechanism-tools"><p role="status">${esc(feedback)}</p><div>${task.kind==='pairs'?`<button data-do="inspect-task">${world.mechanism?.inspect?'All pairs':'Read closely'}</button>`:''}<button data-do="hint">Hint</button><button data-do="speech-text">Reading</button><button data-do="reset">Reset</button></div></div>`;}
async function show(){if(busy||!world)return;busy=true;try{world.hideMechanism();e=route();nav.state=e;nav.enableTraversal('relaxed');world.partner=$('#partner').value;world.setArea(e.area);await world.loadForm(Number($('#form').value));const node=activeNode(e);nav.restore(approachPoint(node));world.setView(false,node.id);world.paused=true;task=makeTask(units.find(u=>u.id===e.unitId),$('#type').value,node.id,node.id,{},Number($('#form').value));e.active=task;feedback='Tap the pieces on the mechanism. Review progress is temporary.';render();$('#status').textContent='';}catch(error){console.error(error);$('#status').textContent='The 3D gate review could not start. Use a browser with WebGL enabled. Your game saves are untouched.';}finally{busy=false;}}
$('#task-layer').addEventListener('click',event=>{const b=event.target.closest('[data-do]');if(!b||b.disabled||!task)return;const d=b.dataset;if(d.do==='inspect-task'){world.mechanism.inspect=!world.mechanism.inspect;feedback='Choose a question to read it with all three answers.';render();return;}if(d.do==='review'){$('#options').showModal();return;}if(d.do==='reset'){show();return;}if(d.do==='hint'){feedback=taskHint(task);render();return;}if(d.do==='speech-text'){task.showSpeech=!task.showSpeech;render();return;}if(d.do==='listen'){const text=d.text||task.pairs?.[Number(d.index)]?.spoken;if(text&&'speechSynthesis'in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-GB';speechSynthesis.speak(u);}return;}const kind={'pair-left':'left','pair-right':'right',block:'block',choice:'choice',find:'find',pick:'pick',confirm:'confirm'}[d.do];if(!kind)return;const action={kind,...(d.index!==undefined?{index:Number(d.index)}:{}),...(d.text!==undefined?{text:d.text}:{})},r=actTask(task,action);if(r.accepted)world.mechanism.accept(action,task.type,task);else if(r.wrong)world.mechanism.reject(action);feedback=r.complete?'Mechanism restored. Reset to inspect it again.':r.wrong?'Try again. Correct work stays fitted.':r.accepted?'The mechanism responds.':'Now choose its matching piece.';render();});
$('#apply').onclick=()=>{$('#options').close();show();};$('#dismiss').onclick=()=>$('#options').close();
try{units=(await(await fetch('data/expedition-language.json')).json()).units;$('#type').innerHTML=TASK_TYPES.map(t=>`<option value="${t}">${esc(activity(t).label)}</option>`).join('');$('#unit').innerHTML=units.map(u=>`<option value="${u.id}">${esc(u.id+' · '+u.title)}</option>`).join('');$('#form').innerHTML=Array.from({length:11},(_,i)=>`<option value="${i}"${i===3?' selected':''}>Level ${i}</option>`).join('');e=route();nav=new TrailNavigator(e);nav.enableTraversal('relaxed');world=new TrailWorld($('#world'),()=>{},nav);world.onFrame=()=>{world.measurementPhase='task';};applyGraphics(world,graphicsSettings({preset:'balanced'}),devicePixelRatio);await show();}catch(error){console.error(error);$('#status').textContent='The 3D gate review could not start. Use a browser with WebGL enabled. Your game saves are untouched.';}
